#!/usr/bin/perluse DBI;use utf8;#use Encode;#binmode STDOUT,":utf8";my @SuraNames=("","الفاتحة","البقرة","ال عمران","النساء","المائدة","الانعام","الاعراف","الانفال","التوبة","يونس","هود","يوسف","الرعد","ابراهيم","الحجر","النحل","الاسراء","الكهف","مريم","طه","الانبياء","الحج","المؤمنون","النور","الفرقان","الشعراء","النمل","القصص","العنكبوت","الروم","لقمان","السجدة","الاحزاب","سبأ","فاطر","يس","الصافات","ص","الزمر","غافر","فصلت","الشورى","الزخرف","الدخان","الجاثية","الاحقاف","محمد","الفتح","الحجرات","ق","الذاريات","الطور","النجم","القمر","الرحمن","الواقعة","الحديد","المجادلة","الحشر","الممتحنة","الصف","الجمعة","المنافقون","التغابن","الطلاق","التحريم","الملك","القلم","الحاقة","المعارج","نوح","الجن","المزمل","المدثر","القيامة","الانسان","المرسلات","النبا","النازعات","عبس","التكوير","الانفطار","المطففين","الانشقاق","البروج","الطارق","الاعلى","الغاشية","الفجر","البلد","الشمس","الليل","الضحى","الشرح","التين","العلق","القدر","البينة","الزلزلة","العاديات","القارعة","التكاثر","العصر","الهمزة","الفيل","قريش","الماعون","الكوثر","الكافرون","النصر","المسد","الاخلاص","الفلق","الناس",);#my $text="ۛ فِيهِ ۛ هُدًى لِلْمُتَّقِينَ";#$text=~ s/([\x{06D6}-\x{06DC}])/\<span class=ps\>$1\<\/span\>/gi;#$text=~ s/([\x{06D6}-\x{06DC}])/\<span class=ps\>$1\<\/span\>/gi;#print $text . "\n";#print @SuraNames[3] . "\nCheck UTF8:" . utf8::valid(@SuraNames[3]);my $curr_page={number=>0,sura=>0,aya=>0};my $curr_sajda={number=>1,sura=>7,aya=>206};my $curr_part={number=>1,sura=>1,aya=>1};#if(my $dbh=qutils::db_connect("cgi.muslim-web.com"))if(my $dbh=DBI->connect("DBI:mysql:database=quran;host=localhost","root","kobool_2004")){#print "mysql_enable_utf8:" . $dbh->{mysql_enable_utf8};$dbh->do("SET NAMES utf8");my $sth=$dbh->prepare(q(select*from quran_text where sura=?));my $basmalah="بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ";for(my $sura=1;$sura<=114;$sura++){my $sura_str=DecToString($sura,3);if($curr_page->{sura}<$sura){$curr_page=get_page_info($dbh,$curr_page->{number}+1);}my $first_page=(($curr_page->{sura}==$sura)&&($curr_page->{aya}==1))?$curr_page->{number}:$curr_page->{number}- 1;my $last_page=$first_page;open STDOUT,">:encoding(UTF-8)","sura_${sura_str}.shtml";print STDOUT qq<<html><head><!--#include virtual="/sura_inc_header.html"--><script language="JavaScript">var gFirstPage=$first_page</script></head><body DIR="RTL" bgcolor="#efefde" onload="onSuraLoad()"><div style="border:solid 1px silver;background:#dcdcb6"><span id="idPage" aya="1">(ص $first_page)</span><span>($sura)سورة @SuraNames[$sura]</span></div>>;$sth->execute($sura);if($sura !=1&&$sura !=9){print STDOUT "<p id=idBasm>$basmalah</p>\n";}my $aya=1;while(my $row=$sth->fetchrow_hashref){if($sura==$curr_part->{sura}&&$aya==$curr_part->{aya}){print STDOUT "<p id=idPart>(الجزء $curr_part->{number})</p>\n";$curr_part=get_part_info($curr_part->{number}+1);}if($sura==$curr_page->{sura}&&$aya==$curr_page->{aya}){if($aya>1){print STDOUT qq(\t\t<p id=idPage pageNo=$curr_page->{number}aya=$aya>(ص $curr_page->{number})</p>\n);}$last_page=$curr_page->{number};$curr_page=get_page_info($dbh,$curr_page->{number}+1);}my $aya_text=$row->{text};utf8::decode($aya_text);#Encode::from_to($aya_text,"utf8","utf8");if($aya==1){if($sura==1){$basmalah=$aya_text;}else{$aya_text=~ s/$basmalah}}#$dbh->do(q(update quran_data set(aya_text=?)where sura=?and aya=?),$aya_text,$sura - 1,$aya -1)$aya_text=~ s/([\x{06D6}-\x{06FF}])/\<span class=ps\>$1\<\/span\>/gi;print STDOUT qq{\t\t<p id=idAya><A NAME=$aya></A><img id="idBullet" width="14" height="14" onmouseover="enterBulletMenu($aya)" onmouseout="leaveMenu()">&nbsp;$aya_text<a href="javascript:ac($aya)">($aya)</a>\n };if($sura==$curr_sajda->{sura}&&$aya==$curr_sajda->{aya}){print STDOUT qq{\t\t<div>(س)</div>\n};$curr_sajda=get_sajda_info($curr_sajda->{number}+1);}$aya++;}print STDOUT qq(<div style="height:400px"></div><script language="JavaScript">var gSuraNo=$sura;var gLastPage=$last_page;writeMenu();</script></body></html>);close STDOUT;}$sth->finish;$dbh->disconnect;}sub get_page_info{# returns sura and ayamy $dbh=shift;my $page_number=shift;my $sth=$dbh->prepare("select*from pages where id=?");$sth->execute($page_number);my $page_info=$sth->fetchrow_hashref;if($page_info){$page_info->{number}=$page_number;return $page_info;}return{number=>0,sura=>0,aya=>0};}sub get_part_info{my $part_number=shift;my $part_index=($part_number - 1)*2;my @Parts=(1,1,2,142,2,253,3,93,4,24,4,149,5,82,6,111,7,88,8,41,9,93,11,6,12,53,15,1,17,1,18,75,21,1,23,1,25,21,27,56,29,46,33,31,36,28,39,32,41,47,46,1,51,31,58,1,67,1,78,1);return{number=>$part_number,sura=>@Parts[$part_index ],aya=>@Parts[$part_index+1]};}sub get_sajda_info{my $sajda_number=shift;my $sajda_index=($sajda_number - 1)*2;my @sajadat=(7,206,13,15,16,50,17,109,19,58,22,18,22,77,25,60,27,26,32,15,38,24,41,38,53,62,84,21,96,19);return{number=>$sajda_number,sura=>@sajadat[$sajda_index ],aya=>@sajadat[$sajda_index+1]};}sub DecToString{my $nValue=shift;my $nDigits=shift;my $sValue="$nValue";while(length($sValue)<$nDigits){$sValue="0" . $sValue;}return $sValue;}